/* eslint-disable no-undef */
import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  Watch,
} from '@stencil/core';
import {
  ButtonGroupChangeEventDetails,
  ButtonGroupIconPosition,
  ButtonGroupMode,
  ButtonGroupSize,
  ButtonGroupVariant,
} from '../../types';

/**
 * @nativeEvent click  - dispatched when button was clicked => 'event.target.value' delivers the value of the clicked button
 * @nativeEvent change - dispatched when the selection has changed => 'event.detail' delivers the current selection state as an object with value (value) and content (innerText)
 * */
@Component({
  tag: 'groupui-button-group',
  styleUrl: 'button-group.scss',
  shadow: true,
})
export class ButtonGroup implements ComponentInterface {
  private static readonly CSS_VALUE_UNIT_REGEX = /^([+-]?(?:\d+|\d*\.\d+))([a-z]*|%)$/;

  @Element() host: HTMLElement;

  /**
   * activates an inverted presentation of the group and the nested buttons
   */
  @Prop({ reflect: true }) readonly inverted: boolean;

  /**
   * sets the button-group to fullwidth and every child to grow with same width
   */
  @Prop({ reflect: true }) readonly fullwidth: boolean;

  /**
   * mode of the button-group
   */
  @Prop({ reflect: true }) readonly mode?: ButtonGroupMode = 'button';

  /**
   * variant of the button-group
   */
  @Prop({ reflect: true }) readonly variant: ButtonGroupVariant = 'primary';

  /**
   * deactivates the button-group
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * used to be referenced in a form
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * sets a gap between the individual buttons
   */
  @Prop({ reflect: true }) readonly gap: string;

  /**
   * sets the size
   */
  @Prop({ reflect: true }) readonly size: ButtonGroupSize = 'm';

  /**
   * sets the icon position
   */
  @Prop({ reflect: true }) readonly iconPosition: ButtonGroupIconPosition = 'left';

  /**
   * sets icon only mode
   */
  @Prop({ reflect: true }) readonly iconOnly: boolean;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * for react user only - is dispatched when the checked state is changed
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<ButtonGroupChangeEventDetails>;

  @Watch('disabled')
  updateDisabledPropOfChild() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      groupButton.disabled = this.disabled;
    });
  }

  @Watch('inverted')
  updateInvertedPropOfChild() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      groupButton.inverted = this.inverted;
    });
  }

  @Watch('fullwidth')
  updateFullwidthPropOfChild() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      groupButton.samewidth = this.fullwidth;
    });
  }

  @Watch('size')
  updateSizePropOfChild() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      groupButton.size = this.size;
    });
  }

  @Watch('variant')
  updateVariantPropOfChild() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      groupButton.variant = this.variant;
    });
  }

  @Watch('iconPosition')
  updateIconPositionPropOfChild() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      groupButton.iconPosition = this.iconPosition;
    });
  }

  @Watch('iconOnly')
  updateIconOnlyPropOfChild() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      groupButton.iconOnly = this.iconOnly;
    });
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Space') {
      if (!this.disabled) {
        this.handleClick({ ...event, target: document.activeElement });
      }
      event.preventDefault();
    }
    if (event.code === 'Enter') {
      if (!this.disabled) {
        this.handleClick({ ...event, target: document.activeElement });
      }
    }
  }

  @Listen('click')
  handleClick(event: Event) {
    const button = (event.target as HTMLElement).closest('groupui-button-group-button');
    if (!button) return;
    switch (this.mode) {
      case 'checkbox': {
        this.toggleCheckbox(button);
        this.host.dispatchEvent(this.changeEvent());
        this.groupuiChange.emit(this.changeEventPayload());
        break;
      }
      case 'radio': {
        if (this.selectRadioButton(button)) {
          this.host.dispatchEvent(this.changeEvent());
          this.groupuiChange.emit(this.changeEventPayload());
        }
      }
    }
  }

  private initializeButtonGroupButtons() {
    const groupButtons = this.buttonGroupButtons();
    groupButtons.forEach((groupButton: HTMLGroupuiButtonGroupButtonElement) => {
      if (this.inverted !== undefined) groupButton.inverted = this.inverted;
      if (this.fullwidth !== undefined) groupButton.samewidth = this.fullwidth;
      if (this.disabled !== undefined) groupButton.disabled = this.disabled;
      if (this.iconOnly !== undefined) groupButton.iconOnly = this.iconOnly;
      if (this.name !== undefined) groupButton.name = this.name;
      if (this.size !== undefined) groupButton.size = this.size;
      if (this.variant !== undefined) groupButton.variant = this.variant;
      if (this.iconPosition !== undefined) groupButton.iconPosition = this.iconPosition;
    });
    this.updatePositionProperty();
  }

  private toggleCheckbox(button: HTMLGroupuiButtonGroupButtonElement) {
    button.checked = !button.checked;
  }

  private selectRadioButton(button: HTMLGroupuiButtonGroupButtonElement): boolean {
    if (button.checked) return false;
    this.uncheckAll();
    button.checked = true;
    return true;
  }

  private uncheckAll() {
    Array.from(this.buttonGroupButtons()).forEach(
      (button: HTMLGroupuiButtonGroupButtonElement) => (button.checked = false)
    );
  }

  private changeEvent(): CustomEvent {
    return new CustomEvent('change', { detail: this.changeEventPayload() });
  }

  private changeEventPayload(): ButtonGroupChangeEventDetails {
    return this.checkedButtons().map((button) => {
      return { value: button.value, content: button.innerText };
    });
  }

  private checkedButtons(): HTMLGroupuiButtonGroupButtonElement[] {
    return Array.from(this.buttonGroupButtons()).filter(
      (button: HTMLGroupuiButtonGroupButtonElement) => button.checked
    );
  }

  componentWillRender() {
    this.initializeButtonGroupButtons();
    this.updateGapProperty();
  }

  private updatePositionProperty() {
    const buttons = this.buttonGroupButtons();
    buttons.forEach((button, i) => {
      switch (i) {
        case 0:
          button.setAttribute('position', 'first');
          break;
        case buttons.length - 1:
          button.setAttribute('position', 'last');
          break;
        default:
          button.setAttribute('position', 'middle');
      }
    });
  }

  @Watch('gap')
  onGapChanged() {
    this.updateGapProperty();
    this.updateSpacedProperty();
  }

  private onSlotChange = async () => {
    this.updateGapProperty();
    this.updateSpacedProperty();
    this.updatePositionProperty();
    await this.setRoles();
  };

  private updateGapProperty() {
    if (this.gap) {
      this.host.style.setProperty('--gap', this.gap);
    } else {
      this.host.style.removeProperty('--gap');
    }
    this.updateSpacedProperty();
  }

  private updateSpacedProperty() {
    if (this.gap) {
      const parts = this.gap.match(ButtonGroup.CSS_VALUE_UNIT_REGEX);
      if (parseFloat(parts[1]) > 0) {
        this.buttonGroupButtons().forEach((b) => (b.spaced = true));
      } else {
        this.buttonGroupButtons().forEach((b) => b.removeAttribute('spaced'));
      }
    } else {
      this.buttonGroupButtons().forEach((b) => b.removeAttribute('spaced'));
    }
  }

  componentWillLoad() {
    if (this.name) {
      this.buttonGroupButtons().forEach((button) => {
        button.name = this.name;
      });
    }
  }

  private buttonGroupButtons(): HTMLGroupuiButtonGroupButtonElement[] {
    return Array.from(this.host.querySelectorAll('groupui-button-group-button'));
  }

  private async waitForHydrated(element: HTMLElement): Promise<void> {
    return new Promise((resolve) => {
      if (element.classList.contains('hydrated')) {
        return resolve();
      }

      const observer = new MutationObserver(() => {
        if (element.classList.contains('hydrated')) {
          observer.disconnect();
          resolve();
        }
      });

      observer.observe(element, {
        attributes: true,
        attributeFilter: ['class'],
      });
    });
  }

  private async setRoles() {
    let buttonRole: string;
    let hostRole: string;

    switch (this.mode) {
      case 'radio':
        buttonRole = 'radio';
        hostRole = 'radiogroup';
        break;
      case 'checkbox':
        buttonRole = 'checkbox';
        hostRole = 'group';
        break;
      default:
        buttonRole = 'button';
        hostRole = 'group';
        break;
    }

    for (const button of this.buttonGroupButtons()) {
      await this.waitForHydrated(button);
      button.shadowRoot.querySelector('#button')?.setAttribute('role', buttonRole);
    }
    this.host.setAttribute('role', hostRole);
  }

  async componentDidLoad() {
    const buttons = this.buttonGroupButtons();
    buttons.forEach((button) => {
      button.hasAttribute('autofocus') && button.getAttribute('autofocus') !== 'false' && button.focus();
    });

    await this.setRoles();

    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host>
        <slot onSlotchange={this.onSlotChange} />
      </Host>
    );
  }
}
